/**
 * Photography index (trip cards) and per-trip masonry gallery.
 * Each trip's photo list comes from {folder}/photos.json, generated by build-photos.sh.
 */

import data from './data.js';
import { $ } from './dom.js';
import { openLightbox } from './lightbox.js';

export function renderTrips() {
    const grid = $('.trips-grid');
    if (!grid) return;

    grid.innerHTML = data.photoTrips.map(trip => `
        <a href="/gallery?trip=${trip.slug}" class="trip-card">
            <img src="/${trip.folder}/${trip.cover}" alt="${trip.title}" loading="lazy" />
            <div class="trip-card-overlay">
                <h3 class="trip-card-title">${trip.title}</h3>
                <span class="trip-card-year">${trip.year}</span>
            </div>
        </a>
    `).join('');
}

export async function renderGallery() {
    const gallery = $('.masonry-gallery');
    if (!gallery) return;

    const slug = new URLSearchParams(window.location.search).get('trip');
    const trip = data.photoTrips.find(t => t.slug === slug);
    if (!trip) {
        gallery.innerHTML = '<p class="placeholder">Trip not found.</p>';
        return;
    }

    document.title = `${trip.title} - Alice Li`;
    $('.gallery-subtitle').textContent = `${trip.title}, ${trip.year}`;
    $('.gallery-title').textContent = trip.title;

    const photos = (await fetchTripPhotos(trip.folder)).map(name => `/${trip.folder}/${name}`);
    gallery.innerHTML = photos.map((src, i) => `
        <div class="masonry-item">
            <img src="${src}" alt="${trip.title} photo ${i + 1}" loading="lazy" data-index="${i}" />
        </div>
    `).join('');

    gallery.addEventListener('click', e => {
        const img = e.target.closest('img[data-index]');
        if (img) openLightbox(photos, Number(img.dataset.index));
    });
}

async function fetchTripPhotos(folder) {
    try {
        const res = await fetch(`/${folder}/photos.json`);
        return await res.json();
    } catch {
        return [];
    }
}
